package com.opensocket.aievent.database.persistence.a2a.repository;
import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Repository;import com.opensocket.aievent.core.a2a.*;import com.opensocket.aievent.database.persistence.a2a.*;import com.opensocket.aievent.database.persistence.a2a.dao.*;
@Repository @ConditionalOnProperty(prefix="task",name="store",havingValue="MYBATIS") public class MybatisA2AReconciliationEvidenceRepository implements A2AReconciliationEvidenceRepository {private final A2AReconciliationEvidenceDao dao;private final A2APersistenceConverter c;public MybatisA2AReconciliationEvidenceRepository(A2AReconciliationEvidenceDao d,A2APersistenceConverter c){dao=d;this.c=c;}public A2AReconciliationEvidence append(A2AReconciliationEvidence v){dao.append(c.toPo(v));return Optional.ofNullable(dao.findByEvent(v.getTenantId(),v.getEventKey())).map(c::toDomain).orElse(v);}public List<A2AReconciliationEvidence> findByCase(String t,String id,int l){return dao.findByCase(t,id,Math.max(1,Math.min(l,500))).stream().map(c::toDomain).toList();}public boolean existsEvent(String t,String k){return dao.findByEvent(t,k)!=null;}public String mode(){return "MYBATIS_APPEND_ONLY";}}
